-- Reviewed crop catalog and user-reported pot setup. Safe to reapply.

-- Back up first. Does not delete or renumber existing crops/plants.

USE defaultdb;

CREATE TABLE IF NOT EXISTS crop_evidence (
 slug VARCHAR(60) PRIMARY KEY, crop_id BIGINT UNSIGNED NOT NULL UNIQUE,
 data JSON NOT NULL, FOREIGN KEY(crop_id) REFERENCES crops(id)
) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS garden_setup (
 user_id BIGINT UNSIGNED PRIMARY KEY,
 depth_cm DECIMAL(7,2) NULL, volume_l DECIMAL(8,3) NULL,
 drainage BOOLEAN NULL, support BOOLEAN NULL,
 method ENUM('seed','seedling') NOT NULL DEFAULT 'seed',
 FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE
) ENGINE=InnoDB;

START TRANSACTION;





















COMMIT;
